usage.code:
import { GlareHover } from "solen-design/react";

<GlareHover
  width={320}
  height={200}
  background="linear-gradient(135deg, #1e1b4b, #831843)"
  borderRadius="16px"
  glareColor="#ffffff"
  glareOpacity={0.5}
  glareAngle={-45}
  glareSize={30}
  softness={0.6}
  variant="streak"
  blendMode="screen"
  rimGlint={true}
  mode="hover"
  transitionDuration={650}
>
  <div>你的内容</div>
</GlareHover>
